begin;
create function public.mir_supplier_stock_queue() returns jsonb language plpgsql stable security definer set search_path=pg_catalog,mir_core as $$declare org uuid;out jsonb;begin select organization_id into org from mir_core.account_settings where singleton;if not mir_core.warehouse_allowed(org) then raise exception 'Entrepôt requis' using errcode='42501';end if;select coalesce(jsonb_agg(jsonb_build_object('id',r.id,'name',l.item_name,'unit',l.unit,'received',r.received_qty,'delivered',r.delivered_qty,'remaining',r.received_qty-r.delivered_qty,'job',c.job,'address',c.delivery_address,'supplierOrderId',r.supplier_order_id)),'[]') into out from mir_core.coordination_routes r join mir_core.coordination_lines l on(l.organization_id,l.id)=(r.organization_id,r.coordination_line_id) join mir_core.coordination_orders c on(c.organization_id,c.id)=(l.organization_id,l.coordination_id) where r.organization_id=org and r.receipt_destination='stock' and r.received_qty>r.delivered_qty;return out;end$$;
revoke all on function public.mir_supplier_stock_queue() from public,anon;grant execute on function public.mir_supplier_stock_queue() to authenticated;
alter function public.mir_administration(text) rename to mir_administration_base;
revoke all on function public.mir_administration_base(text) from public,anon,authenticated;
create function public.mir_administration(p_search text default '') returns jsonb language plpgsql stable security definer set search_path=pg_catalog,mir_core as $$declare out jsonb;org uuid;begin out:=public.mir_administration_base(p_search);select organization_id into org from mir_core.account_settings where singleton;return jsonb_set(out,'{today}',out->'today'||jsonb_build_object('overdue',case when mir_core.coordination_allowed(org) then (select count(*) from mir_core.coordination_routes where organization_id=org and route='supplier' and delivered_qty<quantity and expected_date<current_date) else 0 end,'toSend',case when mir_core.coordination_allowed(org) then(select count(*) from mir_core.orders o where organization_id=org and kind='supplier' and status in('draft','approved') and not exists(select 1 from mir_core.send_jobs j where j.organization_id=org and j.order_id=o.id and j.revision=o.revision and j.status in('accepted','delivered'))) else 0 end));end$$;
revoke all on function public.mir_administration(text) from public,anon;grant execute on function public.mir_administration(text) to authenticated;
create or replace function public.mir_job_blockers(p_job_id uuid default null) returns jsonb language plpgsql stable security definer set search_path=pg_catalog,mir_core as $$declare org uuid;out jsonb;begin
 select organization_id into org from mir_core.account_settings where singleton;
 if not mir_core.has_role(org,array['admin','employee']) then raise exception 'Accès équipe requis' using errcode='42501';end if;
 select coalesce(jsonb_agg(x),'[]') into out from(select jsonb_build_object('jobId',o.job_id,'orderId',o.id,'coordinationId',c.id,'routeId',r.id,'supplierOrderId',r.supplier_order_id,'quantity',r.quantity-r.delivered_qty,'unit',l.unit,'name',l.item_name,'expectedDate',r.expected_date,'overdue',r.expected_date<current_date,'responsible',coalesce(p.name,case when m.role='admin' then 'Administration' end,'Adjointe à attribuer'),'destination',r.receipt_destination,'message',(r.quantity-r.delivered_qty)::text||' '||l.unit||case when r.receipt_destination='stock' and r.received_qty>r.delivered_qty then ' à livrer depuis le stock · ' else ' attendus du fournisseur · ' end||coalesce(r.expected_date::text,'Date à confirmer')||' · suivi par '||coalesce(p.name,case when m.role='admin' then 'l’administration' end,'l’adjointe à attribuer')) x from mir_core.orders o join mir_core.coordination_orders c on(c.organization_id,c.employee_order_id)=(o.organization_id,o.id) join mir_core.coordination_lines l on(l.organization_id,l.coordination_id)=(c.organization_id,c.id) join mir_core.coordination_routes r on(r.organization_id,r.coordination_line_id)=(l.organization_id,l.id) left join mir_core.staff_profiles p on p.organization_id=org and p.user_id=r.responsible_id left join mir_core.memberships m on m.organization_id=org and m.user_id=r.responsible_id where o.organization_id=org and r.route='supplier' and r.delivered_qty<r.quantity and (p_job_id is null or o.job_id=p_job_id) and (mir_core.coordination_allowed(org) or mir_core.job_allowed(org,o.job_id))) q;return out;
end$$;

commit;
